#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    const ll INF = (1LL << 60);

    /*
      DP over the sign/state of current value.

      For each A_i, after k operations:
        value = A_i * (-2)^k

      Possible forms:
        even k:  positive, value = A_i * 4^t, cost = 2t
        odd  k:  negative, value = -2*A_i * 4^t, cost = 2t+1

      Let dpPos = minimum operations up to previous element, if previous chosen value is positive
          dpNeg = minimum operations up to previous element, if previous chosen value is negative

      But we also need the smallest possible previous value among solutions with that cost behavior.
      Instead, we can greedily keep the minimum achievable current value for each parity/sign with exact minimal cost.

      State:
        For current prefix, among all ways with minimal cost ending at positive, keep smallest current value posVal.
        Similarly for negative, keep smallest current value negVal.

      Transition:
        Given previous value x and next base a, find minimum extra ops to make new value y >= x
        where y is either positive-form or negative-form.

      Since multiplying by 4 preserves sign and increases magnitude monotonically,
      minimum t can be found by repeated multiplication. Total repetitions over all transitions is small enough
      because values grow exponentially and 64-bit limits bound iterations (~32).
    */

    ll dpPos = INF, dpNeg = INF;
    ll posVal = 0, negVal = 0;

    // Initialize with first element
    dpPos = 0;
    posVal = A[0];

    dpNeg = 1;
    negVal = -2 * A[0];

    for (int i = 1; i < N; i++) {
        ll a = A[i];

        ll ndpPos = INF, ndpNeg = INF;
        ll nposVal = 0, nnegVal = 0;

        // helper transitions from a previous state (cost, prevVal)
        for (int s = 0; s < 2; s++) {
            ll curCost = (s == 0 ? dpPos : dpNeg);
            ll prevVal = (s == 0 ? posVal : negVal);
            if (curCost >= INF) continue;

            // Transition to negative: y = -2*a*4^t, cost add 2t+1
            // Need prevVal <= y < 0, so possible only if prevVal < 0.
            if (prevVal < 0) {
                ll y = -2 * a;
                ll add = 1;
                // Need y >= prevVal. Since y decreases as multiplied by 4 (more negative),
                // the best is t=0 only. If t=0 fails, larger t won't help.
                if (y >= prevVal) {
                    ll total = curCost + add;
                    if (total < ndpNeg || (total == ndpNeg && y < nnegVal)) {
                        ndpNeg = total;
                        nnegVal = y;
                    }
                }
            }

            // Transition to positive: y = a*4^t, cost add 2t
            // Need y >= prevVal.
            {
                ll y = a;
                ll add = 0;
                while (y < prevVal) {
                    if (y > LLONG_MAX / 4) { y = LLONG_MAX; add = INF; break; }
                    y *= 4;
                    add += 2;
                    if (add >= INF) break;
                }
                if (add < INF) {
                    ll total = curCost + add;
                    if (total < ndpPos || (total == ndpPos && y < nposVal)) {
                        ndpPos = total;
                        nposVal = y;
                    }
                }
            }
        }

        dpPos = ndpPos;
        dpNeg = ndpNeg;
        posVal = nposVal;
        negVal = nnegVal;
    }

    ll ans = dpPos < dpNeg ? dpPos : dpNeg;
    if (ans >= INF) printf("-1\n");
    else printf("%lld\n", ans);

    free(A);
    return 0;
}

