    vector<int64> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    // Possible values after k operations: value = A[i] * (-2)^k
    // We only consider k = 0,1,2,3 because beyond that absolute value grows huge
    // and can't be useful for small constraints.
    vector<vector<int64>> val(N, vector<int64>(4));
    for (int i = 0; i < N; i++) {
        val[i][0] = A[i];
        val[i][1] = -2 * A[i];
        val[i][2] = 4 * A[i];
        val[i][3] = -8 * A[i];
    }

    vector<vector<int64>> dp(N, vector<int64>(4, INF));
    for (int k = 0; k < 4; k++) dp[0][k] = k;

    for (int i = 1; i < N; i++) {
        for (int k2 = 0; k2 < 4; k2++) {
            for (int k1 = 0; k1 < 4; k1++) {
                if (dp[i-1][k1] == INF) continue;
                if (val[i-1][k1] <= val[i][k2]) {
                    dp[i][k2] = min(dp[i][k2], dp[i-1][k1] + k2);
                }
            }
        }
    }

    int64 ans = INF;
    for (int k = 0; k < 4; k++) ans = min(ans, dp[N-1][k]);
    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

