#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    const long long INF = (1LL << 60);

    // For each i, after k operations:
    // value = A[i] * (-2)^k
    // k even -> positive, magnitude A[i] * 2^k
    // k odd  -> negative, magnitude A[i] * 2^k
    //
    // Since A[i] > 0, for fixed parity:
    // - even values form increasing sequence: A, 4A, 16A, ...
    // - odd  values form decreasing sequence: -2A, -8A, -32A, ...
    //
    // DP over the last chosen state:
    // dp_even = minimum ops up to current position if current chosen k is even
    //           and among feasible even k we keep the smallest possible value
    //           for that minimum.
    // dp_odd similarly for odd.
    //
    // But comparing only smallest value is enough because transition feasibility
    // for next element depends only on previous value, and smaller previous value
    // is always better.
    //
    // So we store:
    // cost_even, val_even
    // cost_odd,  val_odd
    //
    // For each previous state, compute the minimum k of desired parity such that
    // new_value >= prev_value.

    auto next_even = [&](long long a, long long prev) -> pair<long long,long long> {
        // Find minimum even k >= 0 such that a * (-2)^k >= prev.
        // Even k => value = a * 2^k > 0.
        // If prev <= a, k=0 works.
        if (prev <= a) return {0, a};

        // Need a * 2^k >= prev with k even.
        // Let k be smallest even satisfying this.
        long long val = a;
        long long k = 0;
        while (val < prev) {
            if (val > (long long)4e18 / 4) return {INF, INF};
            val *= 4; // increase by 2 in exponent to keep parity even
            k += 2;
            if (k > 100) break;
        }
        return {k, val};
    };

    auto next_odd = [&](long long a, long long prev) -> pair<long long,long long> {
        // Find minimum odd k >= 1 such that a * (-2)^k >= prev.
        // Odd k => value is negative: -a*2^k.
        // Thus possible only if prev is negative, and we need -a*2^k >= prev.
        // Equivalent to a*2^k <= -prev.
        // Since k odd and value decreases as k increases, the minimum odd k is best.
        long long val = -2 * a; // k=1
        if (val >= prev) return {1, val};

        // Increasing odd k makes val more negative, so impossible afterwards.
        return {INF, INF};
    };

    long long cost_even = 0, val_even = A[0];      // k=0
    long long cost_odd  = 1, val_odd  = -2 * A[0]; // k=1

    for (int i = 1; i < N; i++) {
        long long ncost_even = INF, nval_even = INF;
        long long ncost_odd = INF, nval_odd = INF;

        // Transition to even
        if (cost_even < INF) {
            auto [add, v] = next_even(A[i], val_even);
            if (add < INF) {
                long long c = cost_even + add;
                if (c < ncost_even || (c == ncost_even && v < nval_even)) {
                    ncost_even = c;
                    nval_even = v;
                }
            }
        }
        if (cost_odd < INF) {
            auto [add, v] = next_even(A[i], val_odd);
            if (add < INF) {
                long long c = cost_odd + add;
                if (c < ncost_even || (c == ncost_even && v < nval_even)) {
                    ncost_even = c;
                    nval_even = v;
                }
            }
        }

        // Transition to odd
        if (cost_even < INF) {
            auto [add, v] = next_odd(A[i], val_even);
            if (add < INF) {
                long long c = cost_even + add;
                if (c < ncost_odd || (c == ncost_odd && v < nval_odd)) {
                    ncost_odd = c;
                    nval_odd = v;
                }
            }
        }
        if (cost_odd < INF) {
            auto [add, v] = next_odd(A[i], val_odd);
            if (add < INF) {
                long long c = cost_odd + add;
                if (c < ncost_odd || (c == ncost_odd && v < nval_odd)) {
                    ncost_odd = c;
                    nval_odd = v;
                }
            }
        }

        cost_even = ncost_even;
        val_even = nval_even;
        cost_odd = ncost_odd;
        val_odd = nval_odd;
    }

    long long ans = min(cost_even, cost_odd);
    if (ans >= INF) ans = -1;
    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLong();
        }

        // Each element can be in two states: original (state 0) or multiplied by -2 (state 1)
        // We'll use DP to find minimal flips to make sequence non-decreasing.
        int INF = 1_000_000;
        int[][] dp = new int[N][2];
        dp[0][0] = 0;
        dp[0][1] = 1;

        for (int i = 1; i < N; i++) {
            Arrays.fill(dp[i], INF);
            long[] valsPrev = {A[i-1], -2 * A[i-1]};
            long[] valsCurr = {A[i], -2 * A[i]};
            for (int prevState = 0; prevState < 2; prevState++) {
                if (dp[i-1][prevState] == INF) continue;
                for (int currState = 0; currState < 2; currState++) {
                    if (valsPrev[prevState] <= valsCurr[currState]) {
                        dp[i][currState] = Math.min(dp[i][currState], dp[i-1][prevState] + currState);
                    }
                }
            }
        }

        int ans = Math.min(dp[N-1][0], dp[N-1][1]);
        System.out.println(ans >= INF ? -1 : ans);
    }
}

