import java.util.*;

public class Main {
    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        // dp over possible number of operations used on current element.
        // After k operations on x:
        // value = x * (-2)^k
        // sign: positive if k even, negative if k odd
        // abs value grows strictly with k
        //
        // Since |A_i| <= typical contest bounds and long is enough for input,
        // only a limited number of k are relevant:
        // once abs becomes larger than every possible previous/next useful bound,
        // extra states are never needed. 61 is enough for long comparisons.
        int K = 62;

        long[] prev = new long[K];
        Arrays.fill(prev, INF);

        // First element: any number of operations
        for (int k = 0; k < K; k++) prev[k] = k;

        for (int i = 1; i < N; i++) {
            long[] cur = new long[K];
            Arrays.fill(cur, INF);

            for (int pk = 0; pk < K; pk++) {
                if (prev[pk] >= INF) continue;
                for (int ck = 0; ck < K; ck++) {
                    if (leq(A[i - 1], pk, A[i], ck)) {
                        cur[ck] = Math.min(cur[ck], prev[pk] + ck);
                    }
                }
            }
            prev = cur;
        }

        long ans = INF;
        for (long v : prev) ans = Math.min(ans, v);
        System.out.println(ans >= INF ? -1 : ans);
    }

    // Compare a * (-2)^ka <= b * (-2)^kb without overflow.
    static boolean leq(long a, int ka, long b, int kb) {
        boolean signA = (ka % 2 == 0); // true => positive
        boolean signB = (kb % 2 == 0);

        if (signA != signB) {
            return !signA; // negative <= positive
        }

        int cmp = compareAbsScaled(a, ka, b, kb);
        if (signA) {
            return cmp <= 0; // positive: usual order
        } else {
            return cmp >= 0; // negative: larger abs means smaller value
        }
    }

    // Compare a*2^ka and b*2^kb by absolute value, without overflow.
    // return -1 if left < right, 0 if equal, 1 if left > right
    static int compareAbsScaled(long a, int ka, long b, int kb) {
        // Compare a << ka and b << kb, but safely.
        // Equivalent to compare a and b*2^(kb-ka), etc.
        if (a == 0 && b == 0) return 0;
        int logA = bitLen(a) + ka;
        int logB = bitLen(b) + kb;
        if (logA != logB) return Integer.compare(logA, logB);

        // Same bit length after scaling, so align by shifting the smaller exponent side if possible.
        if (ka > kb) {
            int d = ka - kb;
            if (d >= 63) return 1;
            long bb = b << d;
            return Long.compareUnsigned(a, bb);
        } else if (kb > ka) {
            int d = kb - ka;
            if (d >= 63) return -1;
            long aa = a << d;
            return Long.compareUnsigned(aa, b);
        } else {
            return Long.compareUnsigned(a, b);
        }
    }

    static int bitLen(long x) {
        return 64 - Long.numberOfLeadingZeros(x);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

